<?php
require_once __DIR__ . '/_bootstrap.php'; customerPostCsrf(); $message='';
if ($_SERVER['REQUEST_METHOD']==='POST') { $first=trim((string)($_POST['first_name']??'')); $last=trim((string)($_POST['last_name']??'')); $email=trim((string)($_POST['email']??'')); $phone=trim((string)($_POST['phone']??'')); if($first===''||$last===''||!filter_var($email,FILTER_VALIDATE_EMAIL)) $message='Please provide a valid name and email.'; else { $s=customerQuery('UPDATE users SET first_name=?, last_name=?, email=?, phone=? WHERE id=?',[$first,$last,$email,$phone,$customerId]); if($s){$customer=array_merge($customer,['first_name'=>$first,'last_name'=>$last,'email'=>$email]);$_SESSION['user']=$customer;$message='Profile updated successfully.';}else $message='We could not save your profile right now.'; } }
$full=customerRows('SELECT first_name,last_name,email,phone FROM users WHERE id=?',[$customerId]); $form=$full[0]??$customer; customerPageStart('My profile',''); ?><div class="cw-title"><div><h1>My profile</h1><p>Keep your contact details current for smooth delivery.</p></div></div><?php if($message): ?><div class="cw-alert"><?=e($message)?></div><?php endif; ?><section class="cw-card" style="max-width:760px"><form class="cw-form" method="post"><?=csrfField()?><div class="cw-grid cw-grid-2"><label>First name<input name="first_name" value="<?=e($form['first_name']??'')?>" required></label><label>Last name<input name="last_name" value="<?=e($form['last_name']??'')?>" required></label><label>Email<input type="email" name="email" value="<?=e($form['email']??'')?>" required></label><label>Phone<input name="phone" value="<?=e($form['phone']??'')?>"></label></div><button class="cw-btn" type="submit">Save changes</button></form></section><?php customerPageEnd(); ?>